use std::io::{self, Read, Write};

/// Shared borrow: reads, cannot modify, and any number may exist at once.
fn total(v: &Vec<i64>) -> i64 {
    let mut s = 0;
    for x in v {
        s += *x;
    }
    s
}

fn largest(v: &Vec<i64>) -> i64 {
    let mut best = i64::MIN;
    for x in v {
        if *x > best {
            best = *x;
        }
    }
    best
}

/// Exclusive borrow: may modify, and must be the only live reference.
fn add_to_all(v: &mut Vec<i64>, d: i64) {
    for x in v.iter_mut() {
        *x += d;
    }
}

fn push_total(v: &mut Vec<i64>) {
    let t = total(v);          // a shared borrow, ended before the push
    v.push(t);
}

fn show(out: &mut dyn Write, label: &str, v: &Vec<i64>) {
    write!(out, "{}", label).unwrap();
    for x in v {
        write!(out, " {}", x).unwrap();
    }
    writeln!(out).unwrap();
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = match it.next() {
        Some(t) => t.parse().unwrap(),
        None => return,
    };
    let d: i64 = it.next().unwrap().parse().unwrap();

    let mut v: Vec<i64> = Vec::new();
    for _ in 0..n {
        v.push(it.next().unwrap().parse().unwrap());
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    if v.is_empty() {
        writeln!(out, "empty").unwrap();
        return;
    }

    writeln!(out, "total {}", total(&v)).unwrap();
    writeln!(out, "largest {}", largest(&v)).unwrap();

    add_to_all(&mut v, d);
    show(&mut out, "added", &v);

    push_total(&mut v);
    show(&mut out, "pushed", &v);

    writeln!(out, "total {}", total(&v)).unwrap();

    io::stdout().flush().ok();
}
